"""Write docs/data-dictionary.md from the models: every table, column, type and help text."""

from pathlib import Path

from django.apps import apps
from django.conf import settings
from django.core.management.base import BaseCommand

CNAP_APPS = ["people", "accounts", "forms_engine", "reporting", "analytics", "outcomes", "audit"]


class Command(BaseCommand):
    help = "Generate docs/data-dictionary.md from the models."

    def handle(self, *args, **options):
        lines = [
            "# Data dictionary",
            "",
            "Generated by `python manage.py data_dictionary`. Do not edit by hand.",
            "",
        ]
        for label in CNAP_APPS:
            config = apps.get_app_config(label)
            lines += [f"## {config.verbose_name} (`{label}`)", ""]
            for model in config.get_models():
                lines += [f"### `{model._meta.db_table}` — {model.__name__}", ""]
                doc = (model.__doc__ or "").strip()
                if doc and not doc.startswith(model.__name__ + "("):
                    lines += [" ".join(doc.split()), ""]
                lines += ["| Column | Type | Null | Notes |", "| --- | --- | --- | --- |"]
                for f in model._meta.get_fields():
                    if not getattr(f, "column", None) or f.auto_created and not f.concrete:
                        continue
                    ftype = f.get_internal_type()
                    if f.is_relation:
                        ftype = f"FK → {f.related_model._meta.db_table}"
                    notes = []
                    if getattr(f, "choices", None):
                        notes.append(", ".join(str(c[0]) for c in f.choices))
                    if f.help_text:
                        notes.append(str(f.help_text))
                    if getattr(f, "unique", False):
                        notes.append("unique")
                    lines.append(
                        f"| {f.column} | {ftype} | {'yes' if f.null else 'no'} | {' — '.join(notes)} |"
                    )
                cons = [c.name for c in model._meta.constraints]
                if cons:
                    lines += ["", "Constraints: " + ", ".join(f"`{c}`" for c in cons)]
                lines.append("")
        out = Path(settings.BASE_DIR) / "docs" / "data-dictionary.md"
        out.write_text("\n".join(lines))
        self.stdout.write(self.style.SUCCESS(f"Wrote {out} ({len(lines)} lines)"))
